package com.bakouan.app.service;

import com.bakouan.app.dto.CongeDefinitions.*;
import com.bakouan.app.dto.CongeRequests;
import org.junit.jupiter.api.Test;
import java.math.*;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class CongeCalculServiceTest {
    private final CongeCalculService service=new CongeCalculService();
    static Politique policy(){Politique p=new Politique();p.setUnite(Unite.JOUR);p.setAttribution(Attribution.DOTATION);p.setDotation(new BigDecimal("20"));p.setProrata(Prorata.AUCUN);p.setArrondi(RoundingMode.UNNECESSARY);p.setPasDecompte(new BigDecimal("0.25"));p.setPriorite(Priorite.EXPIRATION_PUIS_ORIGINE);p.setExpirationReservation(ExpirationReservation.PROTEGER_JUSQUA_DECISION);p.setReportAutorise(false);p.setAnticipationAutorisee(false);p.setPreavisJours(0);p.setDureeMin(new BigDecimal("0.25"));p.setDureeMax(new BigDecimal("100"));p.setJustificatifRequis(false);p.setDemiJourneesAutorisees(true);p.setCircuitAbsencesConfirme(true);p.setDgObligatoire(true);p.setPolitiqueRefus("DEFINITIF");p.setModeleReservationDebitConfirme(true);p.setRhGestionAdministrativeConfirmee(true);p.setDelegationsAutorisees(false);p.setAnnulation(Annulation.RH_PARTIE_NON_PRISE);p.setModificationAvantDebutAutorisee(true);p.setRetourAnticipeAutorise(true);p.setConfirmationRepriseRequise(true);p.setRemplacementRequis(false);p.setPassationRequise(false);p.setChevauchementBloquant(true);return p;}
    static Calendrier calendar(){Calendrier c=new Calendrier();c.setFuseau("Africa/Ouagadougou");for(DayOfWeek d:DayOfWeek.values()){JourTravail day=new JourTravail();day.setJour(d);day.setPlages(new ArrayList<>(List.of(range(Portion.MATIN,"08:00","12:00","0.5"),range(Portion.APRES_MIDI,"13:00","17:00","0.5"))));c.getSemaine().add(day);}return c;}
    static Plage range(Portion portion,String from,String to,String weight){Plage r=new Plage();r.setPortion(portion);r.setDebut(LocalTime.parse(from));r.setFin(LocalTime.parse(to));r.setPoidsJour(new BigDecimal(weight));return r;}
    static CongeRequests.Demande request(LocalDate from,LocalDate to){var r=new CongeRequests.Demande();r.setTypeCode("ANNUEL_TEST");r.setDebut(from);r.setFin(to);r.setPortionDebut(Portion.JOURNEE);r.setPortionFin(Portion.JOURNEE);return r;}
    @Test void saturdayCanBeWorkedAndMondayExcludedByExplicitCalendar(){Calendrier c=calendar();c.getSemaine().get(0).setPlages(List.of());var result=service.calculate(request(LocalDate.of(2026,10,10),LocalDate.of(2026,10,12)),"p",policy(),"c",c);assertThat(result.getQuantite()).isEqualByComparingTo("2");assertThat(result.getJours().get(2).getExclusion()).contains("non travaille");}
    @Test void holidayAndHalfDayKeepExactProvenance(){Calendrier c=calendar();LocalDate start=LocalDate.of(2026,10,8);ExceptionCalendrier e=new ExceptionCalendrier();e.setDate(start.plusDays(1));e.setLibelle("Ferie configure");c.getExceptions().add(e);var r=request(start,start.plusDays(2));r.setPortionDebut(Portion.APRES_MIDI);r.setPortionFin(Portion.MATIN);var result=service.calculate(r,"p",policy(),"calendar-version",c);assertThat(result.getQuantite()).isEqualByComparingTo("1");assertThat(result.getJours().get(1).getExclusion()).isEqualTo("Ferie configure");assertThat(result.getJours()).allMatch(j->j.getCalendrierId().equals("calendar-version"));}
    @Test void partTimeUsesConfiguredWeight(){Calendrier c=calendar();c.getSemaine().forEach(d->d.setPlages(List.of(range(Portion.MATIN,"08:00","10:00","0.25"))));assertThat(service.calculate(request(LocalDate.now(),LocalDate.now()),"p",policy(),"c",c).getQuantite()).isEqualByComparingTo("0.25");}
    @Test void halfDayUnitAndHourUnitExcludeLunch(){var p=policy();p.setUnite(Unite.DEMI_JOUR);assertThat(service.calculate(request(LocalDate.now(),LocalDate.now()),"p",p,"c",calendar()).getQuantite()).isEqualByComparingTo("2");p.setUnite(Unite.HEURE);var r=request(LocalDate.now(),LocalDate.now());r.setHeureDebut(LocalTime.of(11,30));r.setHeureFin(LocalTime.of(13,30));assertThat(service.calculate(r,"p",p,"c",calendar()).getQuantite()).isEqualByComparingTo("1");}
    @Test void prorataAndRoundingFollowExplicitPolicy(){var p=policy();p.setProrata(Prorata.JOURS_CALENDAIRES);p.setArrondi(RoundingMode.DOWN);assertThat(service.prorata(new BigDecimal("10"),LocalDate.of(2026,1,1),LocalDate.of(2026,1,31),LocalDate.of(2026,1,16),LocalDate.of(2026,1,31),p,calendar())).isEqualByComparingTo("5.00");}
    @Test void rejectsAmbiguousCalendarOrOverlappingHoursAndSecondPrecision(){var c=calendar();c.getSemaine().remove(0);assertThatThrownBy(()->service.validateCalendar(c)).hasMessageContaining("sept jours");c.getSemaine().add(c.getSemaine().get(0));assertThatThrownBy(()->service.validateCalendar(c)).hasMessageContaining("sept jours");var p=policy();p.setUnite(Unite.HEURE);var r=request(LocalDate.now(),LocalDate.now());r.setHeureDebut(LocalTime.of(8,0,1));r.setHeureFin(LocalTime.of(10,0));assertThatThrownBy(()->service.calculate(r,"p",p,"c",calendar())).hasMessageContaining("minute");var overlapping=calendar();overlapping.getSemaine().get(0).getPlages().add(range(Portion.MATIN,"09:00","11:00","0.5"));assertThatThrownBy(()->service.validateCalendar(overlapping)).hasMessageContaining("chevauch");}
}
